/**
 * Font loaders pinned to this site's fonts (Inter, Manrope), preloaded.
 * Generated by `npm run fonts:pin` from brand.preset / brand.fonts in
 * site.ts — run it again after changing them. Other font names fall back to
 * the system font. `npm run fonts:all` restores every supported font.
 */

import { Inter, Manrope, Noto_Sans_Ethiopic } from 'next/font/google';
import type { FontName } from '@/config/presets';

const inter = Inter({ subsets: ['latin'], display: 'swap', preload: true });
const manrope = Manrope({ subsets: ['latin'], display: 'swap', preload: true });

// Amharic letters. The browser downloads this file only for a page that has them.
const notoSansEthiopic = Noto_Sans_Ethiopic({
  subsets: ['ethiopic'],
  display: 'swap',
  preload: false,
});
export const ETHIOPIC_FONT = notoSansEthiopic.style.fontFamily;

const systemFont = 'system-ui, sans-serif';

export const FONT_FAMILIES: Record<FontName, string> = {
  Inter: inter.style.fontFamily,
  'DM Sans': systemFont,
  Manrope: manrope.style.fontFamily,
  'Plus Jakarta Sans': systemFont,
  'Space Grotesk': systemFont,
  Montserrat: systemFont,
  Poppins: systemFont,
  'Playfair Display': systemFont,
  Fraunces: systemFont,
  Lora: systemFont,
};
